/* AdLedger — UI & Google Apps Script API client. Không dùng thư viện build. */
(() => {
'use strict';
const CFG = window.ADLEDGER_CONFIG || {};
const C = window.AdLedgerCore;
const KEYS = ['clients','platforms','accounts','campaigns','expenses','payments','closings','users'];
const titles = {users:['Tài khoản đăng nhập','Cấp email Google và phân quyền theo từng khách hàng.','QUẢN LÝ QUYỀN'],settings:['QR & thông tin thanh toán','Tải mã QR của bạn lên để khách quét khi thanh toán.','CẤU HÌNH NHẬN TIỀN'],dashboard:['Tổng quan quảng cáo','Theo dõi ngân sách, chi phí thực tế và thanh toán của tất cả khách hàng.','BÁO CÁO VẬN HÀNH'],settlements:['Đối soát hàng tuần','Tổng hợp tiền quảng cáo, số dư chuyển kỳ và xác nhận số liệu.','QUẢN LÝ ĐỐI SOÁT'],expenses:['Chi phí quảng cáo','Ghi nhận số tiền thực tế đã chi cho từng chiến dịch, từng ngày.','SỔ CHI PHÍ'],payments:['Thanh toán','Theo dõi tiền khách chuyển, hoàn trả và lịch sử giao dịch.','DÒNG TIỀN'],campaigns:['Chiến dịch & ngân sách','Thiết lập ngân sách ngày theo từng khách hàng và nền tảng.','NGÂN SÁCH KẾ HOẠCH'],clients:['Khách hàng','Danh sách khách hàng và số dư khởi tạo.','DANH MỤC'],accounts:['Tài khoản quảng cáo','Phân biệt tài khoản của mình, của khách hoặc bên thứ ba.','DANH MỤC'],platforms:['Nền tảng quảng cáo','Thêm nền tảng mới mà không cần sửa mã nguồn.','DANH MỤC']};
const palette = ['#4e67e7','#1bb394','#f1a64a','#8b68e8','#db6575','#1fa4d1','#67808f'];
const $ = (id) => document.getElementById(id);
const esc = (v) => String(v == null ? '' : v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = (v) => Math.round(Number(v)||0).toLocaleString('vi-VN')+' đ';
const shortMoney = (v) => (Math.abs(Number(v)||0)>=1e6 ? ((Number(v)||0)/1e6).toLocaleString('vi-VN',{maximumFractionDigits:2})+' tr' : (Math.round(Number(v)||0)).toLocaleString('vi-VN')) + (Math.abs(Number(v)||0)>=1e6 ? '' : ' đ');
const dateDisplay = (s) => s ? s.slice(8,10)+'/'+s.slice(5,7)+'/'+s.slice(0,4) : '—';
const id = () => (window.crypto?.randomUUID ? window.crypto.randomUUID() : 'id_'+Date.now()+'_'+Math.random().toString(36).slice(2));
const nowISO = () => {const p=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(x=>[x.type,x.value]));return `${p.year}-${p.month}-${p.day}`;};
const q = (key) => new URLSearchParams(location.search).get(key);
const getBy = (entity, key) => state.data[entity].find(x=>x.id===key);
const nameOf = (entity,key) => getBy(entity,key)?.name || 'Không xác định';
const configured = !!(CFG.API_URL && CFG.GOOGLE_CLIENT_ID);
let state = {mode:'demo',token:'',me:null,page:'dashboard',week:C.monday(nowISO()),client:'all',data:Object.fromEntries(KEYS.map(k=>[k,[]])),paymentConfig:{bank_name:'',account_number:'',account_name:'',transfer_note:'',qr_image:''},busy:false};
const types = {RECEIVE:'Nhận tiền',REFUND:'Hoàn tiền'};
const payStatus=x=>!x.status||x.status==='CONFIRMED'?'CONFIRMED':x.status;
const payLabel=x=>({CONFIRMED:'Admin đã nhận tiền',PENDING:'Khách báo đã chuyển • Chờ Admin',REJECTED:'Đã từ chối'})[payStatus(x)]||'Chưa rõ';
const isAdmin=()=>state.me?.role==='ADMIN';
const isClient=()=>state.me?.role==='CLIENT';
const paymentsSigned = x => payStatus(x)==='CONFIRMED'?(x.type === 'REFUND' ? -1 : 1) * C.num(x.amount):0;
const weeklyExpenses = () => state.data.expenses.filter(x=>x.date>=state.week && x.date<C.addDays(state.week,7) && (state.client==='all' || getBy('campaigns',x.campaign_id)?.client_id===state.client));
const weeklyPayments = () => state.data.payments.filter(x=>x.week_start===state.week && (state.client==='all'||x.client_id===state.client));
const filteredClients = () => state.data.clients.filter(c=>(!isClient()||c.id===state.me.client_id) && (state.client==='all'||state.client===c.id));
const rows = () => filteredClients().map(client=>({...C.calc(state.data,client.id,state.week),client}));
const summary = () => { const a=rows();return {planned:C.total(a,'planned'),spent:C.total(a,'spent'),paid:C.total(a,'paid'),opening:C.total(a,'opening'),ending:C.total(a,'ending')};};
function seedDemo(){
 const base=C.monday(nowISO()); const days=[0,1,2,3,4,5,6];
 const data={clients:[{id:'cl1',name:'Khách hàng A',contact:'Anh Minh',phone:'',opening_balance:'0',note:'Dự án quảng cáo đa nền tảng',active:'TRUE'},{id:'cl2',name:'Khách hàng B',contact:'Chị Linh',phone:'',opening_balance:'500000',note:'Khách hàng lâu năm',active:'TRUE'}],platforms:[{id:'pf1',name:'Facebook Ads',active:'TRUE'},{id:'pf2',name:'Google Shopping',active:'TRUE'},{id:'pf3',name:'ChatGPT Ads',active:'TRUE'},{id:'pf4',name:'TikTok Ads',active:'TRUE'}],accounts:[{id:'ac1',client_id:'cl1',platform_id:'pf1',name:'BM quảng cáo 01',owner:'OWN',active:'TRUE'},{id:'ac2',client_id:'cl1',platform_id:'pf2',name:'Google Merchant 01',owner:'CLIENT',active:'TRUE'},{id:'ac3',client_id:'cl1',platform_id:'pf3',name:'Tài khoản ChatGPT 01',owner:'OWN',active:'TRUE'},{id:'ac4',client_id:'cl2',platform_id:'pf4',name:'TikTok Ads 02',owner:'CLIENT',active:'TRUE'}],campaigns:[{id:'ca1',client_id:'cl1',platform_id:'pf1',account_id:'ac1',name:'Facebook • Lead Ads',daily_budget:'100000',start_date:base,end_date:'',status:'ACTIVE'},{id:'ca2',client_id:'cl1',platform_id:'pf2',account_id:'ac2',name:'Google • Shopping',daily_budget:'100000',start_date:base,end_date:'',status:'ACTIVE'},{id:'ca3',client_id:'cl1',platform_id:'pf3',account_id:'ac3',name:'ChatGPT • Traffic',daily_budget:'100000',start_date:base,end_date:'',status:'ACTIVE'},{id:'ca4',client_id:'cl2',platform_id:'pf4',account_id:'ac4',name:'TikTok • Awareness',daily_budget:'150000',start_date:base,end_date:'',status:'ACTIVE'}],expenses:[],payments:[],closings:[],users:[{id:'demo.admin@gmail.com',email:'demo.admin@gmail.com',name:'Chủ tài khoản',role:'ADMIN',active:'TRUE',client_id:''},{id:'khach.demo@gmail.com',email:'khach.demo@gmail.com',name:'Khách A',role:'CLIENT',active:'TRUE',client_id:'cl1'}]};
 const dayIndex=Math.max(1,Math.min(6,Math.round((new Date(nowISO()+'T12:00:00Z')-new Date(base+'T12:00:00Z'))/86400000)+1));
 for(let i=0;i<dayIndex;i++) { for(const [ci,amount] of [['ca1',97000+i*2100],['ca2',104000+i*1700],['ca3',89000+i*1800],['ca4',128000+i*2500]]) data.expenses.push({id:id(),campaign_id:ci,date:C.addDays(base,i),amount:String(amount),note:'Chi phí thực tế ngày '+(i+1)}); }
 data.payments.push({id:'pay1',client_id:'cl1',week_start:base,date:base,type:'RECEIVE',amount:'1500000',method:'BANK',reference:'Demo 001',note:'Tạm ứng ngân sách đầu tuần',status:'CONFIRMED'});
 data.payments.push({id:'pay2',client_id:'cl2',week_start:base,date:base,type:'RECEIVE',amount:'600000',method:'BANK',reference:'Demo 002',note:'Tạm ứng quảng cáo',status:'CONFIRMED'});
 return data;
}
function persistDemo(){if(state.mode==='demo')try{localStorage.setItem('adledger_demo_v2',JSON.stringify({data:state.data,config:state.paymentConfig}));}catch(e){console.warn('Không lưu được dữ liệu demo:',e);}}
function toast(msg,type=''){const el=$('toast');el.textContent=msg;el.className='toast '+type;setTimeout(()=>el.classList.add('hidden'),3800);}
function sync(msg){$('syncStatus').textContent='● '+msg;}
function setLoading(val){state.busy=val;sync(val?'Đang đồng bộ...':'Đã đồng bộ');}
function showApp(){ $('loginScreen').classList.add('hidden');$('appShell').classList.remove('hidden');$('modeBadge').textContent=state.mode==='demo'?'Dữ liệu Demo':'Google Sheets • Live';$('modeBadge').classList.toggle('live',state.mode==='live');$('userAvatar').textContent=state.mode==='demo'?'DE':(state.me?.name||state.me?.email||'AD').slice(0,2).toUpperCase();$('currentYear').textContent=new Date().getFullYear();$('weekDate').value=state.week;const demoBtn=$('demoRoleBtn');demoBtn.classList.toggle('hidden',state.mode!=='demo');demoBtn.textContent=isClient()?'Quay về Admin':'Xem như khách';render();}
function showLogin(){ $('appShell').classList.add('hidden');$('loginScreen').classList.remove('hidden');$('demoLoginBtn').classList.toggle('hidden',CFG.DEMO_ALLOWED===false);$('loginNotice').textContent=configured?'Đăng nhập bằng tài khoản có trong danh sách Users của Google Sheet.':'Chưa cấu hình kết nối Google. Bạn có thể dùng bản demo để xem trước.';if(configured)initGoogle();}
function enterDemo(){state.mode='demo';state.me={name:'Demo Admin',role:'ADMIN'};try{const data=JSON.parse(localStorage.getItem('adledger_demo_v2')||'null');state.data=data?.data||seedDemo();state.paymentConfig=data?.config||state.paymentConfig;}catch{state.data=seedDemo();}KEYS.forEach(k=>state.data[k]??=[]);showApp();}
async function api(action,body={}){
 let response,text;
 try {response=await fetch(CFG.API_URL,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action,token:state.token,...body})});text=await response.text();}
 catch(err){throw new Error('Không kết nối được Google Apps Script. Kiểm tra URL deploy, chế độ Anyone và kết nối mạng.');}
 if(!response.ok)throw new Error('Apps Script trả HTTP '+response.status+'. Kiểm tra phiên bản triển khai.');
 let result;try{result=JSON.parse(text)}catch{throw new Error('Phản hồi không phải JSON. Kiểm tra Web App đang chạy và quyền truy cập.');}
 if(!result.ok){if(action!=='login'&&['AUTH','NOT_ALLOWED'].includes(result.code))expireSession(result.message);throw new Error(result.message||'Yêu cầu thất bại');}return result.data;
}
function expireSession(msg){localStorage.removeItem('adledger_session');state.token='';state.me=null;state.mode='demo';closeModal();showLogin();$('loginNotice').textContent=msg||'Phiên đăng nhập đã hết hạn. Vui lòng đăng nhập lại.';}
function initGoogle(){
 if(!window.google?.accounts?.id){setTimeout(initGoogle,250);return;}
 window.google.accounts.id.initialize({client_id:CFG.GOOGLE_CLIENT_ID,callback:async r=>{try{const d=await api('login',{idToken:r.credential});state.token=d.session;localStorage.setItem('adledger_session',JSON.stringify({token:d.session,expires:d.expires}));state.mode='live';state.me=d.me;await loadLive();showApp();}catch(e){toast(e.message,'error');$('loginNotice').textContent=e.message;}},auto_select:false});
 $('googleButton').innerHTML='';window.google.accounts.id.renderButton($('googleButton'),{theme:'outline',size:'large',width:330,text:'signin_with',locale:'vi'});
}
async function loadLive(){setLoading(true);try{const d=await api('bootstrap');state.data=d.entities;state.data.users=(d.users||[]).map(u=>({...u,id:u.email}));state.me=d.me;state.paymentConfig=d.paymentConfig||state.paymentConfig;KEYS.forEach(k=>state.data[k]??=[]);if(isClient())state.client=state.me.client_id;sync('Đã đồng bộ');}finally{setLoading(false)}}
async function bootstrap(){
 try{const ss=JSON.parse(localStorage.getItem('adledger_session')||'null');if(configured && ss?.token && new Date(ss.expires)>new Date()){state.token=ss.token;state.mode='live';await loadLive();showApp();return;}}
 catch(e){localStorage.removeItem('adledger_session');state.token='';state.mode='demo';if(configured){showLogin();$('loginNotice').textContent=e.message;return;}}
 if(configured)showLogin();else if(CFG.DEMO_ALLOWED!==false)enterDemo();else showLogin();
}
function lockedInDemo(entity,rec){
 if(state.mode!=='demo'||!['expenses','payments'].includes(entity))return false;
 const ca=entity==='expenses'?getBy('campaigns',rec.campaign_id):null;
 const clientId=entity==='expenses'?ca?.client_id:rec.client_id;
 const week=C.monday(entity==='expenses'?rec.date:rec.week_start);
 return state.data.closings.some(x=>x.client_id===clientId&&x.status==='CONFIRMED'&&x.week_start>=week);
}
async function save(entity,record){
 if(state.busy)return;
 if(lockedInDemo(entity,record)||lockedInDemo(entity,getBy(entity,record.id)||record)) {toast('Kỳ này hoặc kỳ sau đã chốt. Vui lòng mở lại kỳ trước khi sửa dữ liệu.','error');throw new Error('LOCKED');}
 setLoading(true);
 try{ if(state.mode==='live'){if(entity==='users')await api('manageUser',{record});else await api('mutate',{op:'save',entity,record});await loadLive();}else{const arr=state.data[entity];const i=arr.findIndex(x=>x.id===record.id);if(i>=0)arr[i]={...arr[i],...record};else arr.unshift({...record,id:record.id||id()});persistDemo();}toast('Đã lưu thành công','success');render();}
 catch(e){toast(e.message,'error');throw e;}finally{setLoading(false)}
}
async function del(entity,record){
 if(lockedInDemo(entity,record)){toast('Kỳ đã chốt, không thể xóa dữ liệu.','error');return;}
 if(!confirm('Bạn chắc chắn muốn xóa mục này? Dữ liệu có liên quan sẽ được bảo vệ.'))return;
 try{if(state.mode==='live'){setLoading(true);await api('mutate',{op:'delete',entity,record:{id:record.id}});await loadLive();}else{const relations={clients:['accounts','campaigns','payments','closings'],platforms:['accounts','campaigns'],accounts:['campaigns'],campaigns:['expenses']};const ref={accounts:'client_id',campaigns:entity==='platforms'?'platform_id':entity==='accounts'?'account_id':'client_id',payments:'client_id',closings:'client_id',expenses:'campaign_id'};for(const k of relations[entity]||[]){const field=k==='accounts' && entity==='platforms'?'platform_id':ref[k];if(state.data[k].some(x=>x[field]===record.id))throw new Error('Không thể xóa: đã có dữ liệu liên quan. Hãy ẩn hoặc ngừng sử dụng mục này.');}state.data[entity]=state.data[entity].filter(x=>x.id!==record.id);persistDemo();}toast('Đã xóa dữ liệu','success');render();}
 catch(e){toast(e.message,'error')}finally{setLoading(false)}
}
function updateNav(){const allowed=['dashboard','settlements','expenses','payments','campaigns'];if(isClient()&&!allowed.includes(state.page))state.page='dashboard';document.querySelectorAll('[data-admin-only]').forEach(e=>e.classList.toggle('hidden',!isAdmin()));document.querySelectorAll('.nav-item').forEach(b=>{b.classList.toggle('active',b.dataset.page===state.page);b.classList.toggle('hidden',isClient()&&!allowed.includes(b.dataset.page));});$('breadcrumbCurrent').textContent=titles[state.page][0];$('pageTitle').textContent=titles[state.page][0];$('pageDescription').textContent=titles[state.page][1];$('pageEyebrow').textContent=titles[state.page][2];$('sidebar').classList.remove('open');}
function renderFilters(){const el=$('clientFilter');const old=isClient()?state.me.client_id:state.client;el.innerHTML=(isClient()?'':'<option value="all">Tất cả khách hàng</option>')+state.data.clients.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('');if(![...el.options].some(x=>x.value===old))state.client=isClient()?state.me.client_id:'all';else state.client=old;el.disabled=isClient();el.value=state.client;$('weekDate').value=state.week;$('weekLabel').textContent=dateDisplay(state.week)+' — '+dateDisplay(C.addDays(state.week,6));}
function render(){updateNav();renderFilters();const page=state.page;const heading=$('headingAction');const actions={dashboard:`<button class="btn btn-soft" data-action="export">↧ Xuất báo cáo</button>`,settlements:`<button class="btn btn-soft" data-action="print">⎙ In đối soát</button><button class="btn btn-primary" data-action="export">↧ Xuất CSV</button>`,expenses:`<button class="btn btn-soft" data-action="export">↧ Xuất CSV</button><button class="btn btn-primary" data-create="expenses">＋ Ghi chi phí</button>`,payments:`<button class="btn btn-soft" data-action="export">↧ Xuất CSV</button>${isClient()?'<button class="btn btn-primary" data-request-payment>✓ Xác nhận đã thanh toán</button>':'<button class="btn btn-primary" data-create="payments">＋ Ghi khoản đã nhận</button>'}`,campaigns:`<button class="btn btn-primary" data-create="campaigns">＋ Thêm chiến dịch</button>`,clients:`<button class="btn btn-primary" data-create="clients">＋ Thêm khách hàng</button>`,accounts:`<button class="btn btn-primary" data-create="accounts">＋ Thêm tài khoản</button>`,platforms:`<button class="btn btn-primary" data-create="platforms">＋ Thêm nền tảng</button>`,users:`<button class="btn btn-primary" data-create="users">＋ Cấp quyền khách</button>`,settings:''};heading.innerHTML=actions[page];if(!canEdit(page)){heading.querySelectorAll('[data-create]').forEach(b=>b.remove());} $('view').innerHTML=({dashboard,settlements,expenses,payments,campaigns,clients,accounts,platforms,users,settings})[page]();}
function pill(label,color='gray'){return `<span class="pill ${color}"><span class="dot"></span>${esc(label)}</span>`;}
function avatar(name){return `<span class="row-avatar">${esc((name||'?').slice(0,2).toUpperCase())}</span>`;}
function table(headers, body,emptyMessage='Chưa có dữ liệu cho bộ lọc này.') {if(!body)return `<div class="empty"><div class="empty-icon">▦</div>${esc(emptyMessage)}</div>`;return `<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(h=>`<th class="${h.right?'numeric':''}">${esc(h.text||h)}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table></div>`;}
function platformColor(pid){const index=state.data.platforms.findIndex(x=>x.id===pid);return palette[(index<0?0:index)%palette.length]}
function canEdit(e){return isAdmin()||(state.mode==='demo'&&!isClient())||(state.me?.role==='EDITOR'&&e==='expenses');}
function actions(e,x){if(!canEdit(e))return '<td class="actions">—</td>';return `<td class="actions"><button class="action-link" data-edit="${esc(e)}" data-id="${esc(x.id)}">Sửa</button><button class="action-link delete" data-delete="${esc(e)}" data-id="${esc(x.id)}">Xóa</button></td>`;}
function kpi(label,value,detail,icon,tone=''){return `<div class="card kpi"><div class="kpi-top"><span class="kpi-title">${label}</span><span class="kpi-icon ${tone}">${icon}</span></div><div class="kpi-value">${money(value)}</div><div class="kpi-foot">${detail}</div></div>`;}
function dashboard(){const r=rows(),s=summary();const expensesByPlatform=Object.fromEntries(state.data.platforms.map(x=>[x.id,0]));weeklyExpenses().forEach(x=>{const cp=getBy('campaigns',x.campaign_id);if(cp)expensesByPlatform[cp.platform_id]=(expensesByPlatform[cp.platform_id]||0)+C.num(x.amount)});const platformList=state.data.platforms.map(p=>({...p,spend:expensesByPlatform[p.id]||0})).filter(p=>p.spend>0).sort((a,b)=>b.spend-a.spend);const max=Math.max(...platformList.map(x=>x.spend),1);
 const bars=platformList.length?platformList.map(p=>`<div class="platform-row"><div class="platform-name"><span class="platform-dot" style="background:${platformColor(p.id)}"></span>${esc(p.name)}</div><div class="bar-track"><div class="bar-fill" style="background:${platformColor(p.id)};width:${Math.round(p.spend/max*100)}%"></div></div><div class="bar-value">${shortMoney(p.spend)}</div></div>`).join(''):'<div class="empty">Chưa ghi nhận chi phí tuần này</div>';
 const tableBody=r.map(row=>`<tr><td><div class="row-with-avatar">${avatar(row.client.name)}<span><span class="row-title">${esc(row.client.name)}</span><span class="row-sub">${state.data.campaigns.filter(c=>c.client_id===row.clientId).length} chiến dịch</span></span></div></td><td class="numeric">${money(row.planned)}</td><td class="numeric"><strong>${money(row.spent)}</strong></td><td class="numeric">${money(row.paid)}</td><td class="numeric ${row.ending>=0?'text-green':'text-red'} stat-strong">${money(row.ending)}</td><td>${row.status==='CONFIRMED'?pill('Đã chốt','green'):pill('Chưa chốt','orange')}</td></tr>`).join('');
 return `<div class="kpis">${kpi('Ngân sách dự kiến',s.planned,'Tổng ngân sách kế hoạch của kỳ','▥')}${kpi('Chi phí thực tế',s.spent,'Đã ghi nhận theo từng ngày','↗','orange')}${kpi('Tiền đã nhận (ròng)',s.paid,'Đã trừ các khoản hoàn tiền','⇣','green')}${kpi('Số dư cuối kỳ',s.ending,s.ending>=0?'Dương = khách còn tiền':'Âm = khách còn phải trả','◉',s.ending>=0?'green':'red')}</div>
 <div class="grid-two"><div class="panel"><div class="panel-header"><div><div class="panel-title">Chi phí theo nền tảng</div><div class="panel-sub">Phân bổ chi tiêu thực tế của kỳ đang chọn</div></div><button class="panel-link" data-page="expenses">Xem chi tiết →</button></div>${bars}</div><div class="panel"><div class="panel-header"><div><div class="panel-title">Tổng kết kỳ đối soát</div><div class="panel-sub">${dateDisplay(state.week)} — ${dateDisplay(C.addDays(state.week,6))}</div></div></div><div class="summary-box"><div class="summary-line"><span>Số dư đầu kỳ</span><strong>${money(s.opening)}</strong></div><div class="summary-line"><span>Khách đã chuyển (ròng)</span><strong>${money(s.paid)}</strong></div><div class="summary-line"><span>Chi phí quảng cáo thực tế</span><strong>${money(s.spent)}</strong></div><div class="summary-line total"><span>Số dư chuyển sang kỳ sau</span><strong class="${s.ending>=0?'text-green':'text-red'}">${money(s.ending)}</strong></div></div><div class="note-block"><strong>Nguyên tắc:</strong> Số dư cuối = Số dư đầu + Tiền nhận − Chi phí thực tế. Số dư âm là khoản khách còn phải thanh toán.</div></div></div>
 <div class="panel table-panel"><div class="panel-header"><div><div class="panel-title">Đối soát theo khách hàng</div><div class="panel-sub">Tổng hợp theo tuần cho từng khách hàng</div></div><button class="panel-link" data-page="settlements">Xem đối soát →</button></div>${table([{text:'Khách hàng'},{text:'Dự kiến',right:true},{text:'Thực tế',right:true},{text:'Đã nhận',right:true},{text:'Số dư',right:true},{text:'Trạng thái'}],tableBody)}</div>`;
}
function expenses(){const list=weeklyExpenses().slice().sort((a,b)=>b.date.localeCompare(a.date));const body=list.map(x=>{const ca=getBy('campaigns',x.campaign_id);const platform=ca?getBy('platforms',ca.platform_id):null;return `<tr><td><strong>${dateDisplay(x.date)}</strong></td><td><span class="row-title">${esc(ca?.name||'Chiến dịch đã xóa')}</span><span class="row-sub">${esc(nameOf('clients',ca?.client_id))}</span></td><td><span class="badge-platform"><span class="platform-dot" style="background:${platformColor(ca?.platform_id)}"></span>${esc(platform?.name||'—')}</span></td><td class="numeric stat-strong">${money(x.amount)}</td><td>${esc(x.note||'—')}</td>${actions('expenses',x)}</tr>`;}).join('');return `<div class="list-stats"><div class="card mini-stat"><span>Tổng chi phí kỳ này</span><strong>${money(list.reduce((s,x)=>s+C.num(x.amount),0))}</strong></div><div class="card mini-stat"><span>Số lượt ghi nhận</span><strong>${list.length}</strong></div><div class="card mini-stat"><span>Chiến dịch phát sinh</span><strong>${new Set(list.map(x=>x.campaign_id)).size}</strong></div></div><div class="panel table-panel"><div class="panel-header"><div><div class="panel-title">Sổ chi phí quảng cáo</div><div class="panel-sub">Chỉ hiển thị các giao dịch thuộc tuần đang chọn</div></div></div>${table(['Ngày','Chiến dịch / Khách hàng','Nền tảng',{text:'Chi phí',right:true},'Ghi chú','Thao tác'],body)}</div>`;}
function payments(){
 const list=weeklyPayments().slice().sort((a,b)=>String(b.created_at||b.date).localeCompare(String(a.created_at||a.date)));
 const pending= list.filter(x=>payStatus(x)==='PENDING');
 const pendingAll=state.data.payments.filter(x=>payStatus(x)==='PENDING'&&(state.client==='all'||x.client_id===state.client));
 const confirmed=list.filter(x=>payStatus(x)==='CONFIRMED');
 const body=list.map(x=>{
  const status=payStatus(x),color=status==='CONFIRMED'?'green':status==='PENDING'?'orange':'red';
  const buttons=isAdmin()&&status==='PENDING'?`<button class="btn btn-small btn-primary" data-confirm-payment="${esc(x.id)}">✓ Đã nhận được tiền</button><button class="action-link delete" data-reject-payment="${esc(x.id)}">Từ chối</button>`:isAdmin()&&status==='CONFIRMED'?`<button class="action-link" data-edit="payments" data-id="${esc(x.id)}">Sửa</button>`:'—';
  return `<tr><td><strong>${dateDisplay(x.date)}</strong></td><td><span class="row-title">${esc(nameOf('clients',x.client_id))}</span><span class="row-sub">Kỳ ${dateDisplay(x.week_start)}</span></td><td>${pill(payLabel(x),color)}<span class="row-sub">${esc(x.requested_by||'')}</span></td><td class="numeric stat-strong">${x.type==='REFUND'?'-':'+'}${money(x.amount)}</td><td>${esc(x.reference||'—')}</td><td>${esc(x.note||'—')}</td><td class="actions">${buttons}</td></tr>`;
 }).join('');
 const adminQueue=isAdmin()&&pendingAll.length?`<div class="panel table-panel" style="margin-bottom:18px"><div class="panel-header"><div><div class="panel-title">⚠ Thanh toán khách đang chờ xác nhận (${pendingAll.length})</div><div class="panel-sub">Hiển thị tất cả kỳ, kể cả giao dịch thuộc tuần trước. Kiểm tra ngân hàng trước khi xác nhận.</div></div></div>${table(['Ngày','Khách hàng / Kỳ',{text:'Số tiền',right:true},'Mã giao dịch','Hành động'],pendingAll.map(p=>`<tr><td>${dateDisplay(p.date)}</td><td><strong>${esc(nameOf('clients',p.client_id))}</strong><span class="row-sub">Kỳ ${dateDisplay(p.week_start)}</span></td><td class="numeric">${money(p.amount)}</td><td>${esc(p.reference||'—')}</td><td class="actions"><button class="btn btn-small btn-primary" data-confirm-payment="${esc(p.id)}">✓ Đã nhận được tiền</button><button class="action-link delete" data-reject-payment="${esc(p.id)}">Từ chối</button></td></tr>`).join(''))}</div>`:'';
 const bodyHeader=isClient()?`<div class="payment-guide"><strong>Quy trình hai bước:</strong> Bạn quét QR và chuyển khoản → bấm <b>"Xác nhận đã thanh toán"</b> → người quản lý kiểm tra ngân hàng và bấm <b>"Đã nhận được tiền"</b>. Tiền chỉ được tính vào đối soát sau khi quản lý xác nhận.</div>${qrPanel()}`:'';
 return `${bodyHeader}${adminQueue}<div class="list-stats"><div class="card mini-stat"><span>Đã nhận và xác nhận</span><strong>${money(confirmed.filter(x=>x.type==='RECEIVE').reduce((s,x)=>s+C.num(x.amount),0))}</strong></div><div class="card mini-stat"><span>Đang chờ Admin xác nhận</span><strong>${money(pending.reduce((s,x)=>s+C.num(x.amount),0))}</strong></div><div class="card mini-stat"><span>Thu ròng của kỳ</span><strong>${money(list.reduce((s,x)=>s+paymentsSigned(x),0))}</strong></div></div><div class="panel table-panel"><div class="panel-header"><div><div class="panel-title">Lịch sử thanh toán & xác nhận</div><div class="panel-sub">${isAdmin()?`Có ${pending.length} giao dịch khách báo đã chuyển đang chờ bạn đối chiếu ngân hàng.`:'Yêu cầu chờ xác nhận sẽ chưa cộng vào số dư.'}</div></div></div>${table(['Ngày chuyển','Khách hàng / Kỳ','Trạng thái',{text:'Số tiền',right:true},'Mã giao dịch','Ghi chú','Xử lý'],body)}</div>`;
}
function qrPanel(){const p=state.paymentConfig||{};return `<div class="panel payment-qr"><div><div class="panel-title">Thông tin chuyển khoản</div><p class="panel-sub">Quét mã QR do người quản lý cung cấp hoặc nhập số tài khoản.</p>${p.qr_image?`<img class="qr-image" alt="Mã QR thanh toán do quản trị cung cấp" src="${esc(p.qr_image)}">`:'<div class="qr-missing">Chưa cấu hình mã QR nhận tiền</div>'}</div><div class="bank-lines"><div><small>Ngân hàng</small><strong>${esc(p.bank_name||'Chưa cấu hình')}</strong></div><div><small>Chủ tài khoản</small><strong>${esc(p.account_name||'—')}</strong></div><div><small>Số tài khoản</small><strong>${esc(p.account_number||'—')}</strong></div><div><small>Nội dung chuyển khoản gợi ý</small><strong>${esc(p.transfer_note||'Thanh toán chi phí quảng cáo')}</strong></div><button class="btn btn-primary" data-request-payment>✓ Tôi đã chuyển khoản — Xác nhận thanh toán</button></div></div>`;}
function users(){const list=state.data.users||[];const body=list.map(x=>`<tr><td><strong>${esc(x.email)}</strong><span class="row-sub">${esc(x.name||'')}</span></td><td>${pill(x.role==='CLIENT'?'Khách hàng':x.role,x.role==='CLIENT'?'blue':'green')}</td><td>${esc(x.role==='CLIENT'?nameOf('clients',x.client_id):'Toàn hệ thống')}</td><td>${String(x.active).toUpperCase()==='TRUE'?pill('Hoạt động','green'):pill('Tạm khóa','red')}</td><td class="actions"><button class="action-link" data-edit="users" data-id="${esc(x.email)}">Sửa / khóa</button></td></tr>`).join('');return `<div class="note-block">Thêm khách bằng email Google của họ. Chọn <b>vai trò Khách hàng</b> và gắn <b>một khách hàng</b>; hệ thống chỉ trả dữ liệu của khách đó từ Google Apps Script. Không chia sẻ file Google Sheets.</div><div class="panel table-panel"><div class="panel-header"><div class="panel-title">Tài khoản được cấp quyền</div></div>${table(['Email Google','Vai trò','Dữ liệu được xem','Trạng thái','Thao tác'],body)}</div>`;}
function settings(){const c=state.paymentConfig||{};return `<div class="panel settings-panel"><div class="panel-header"><div><div class="panel-title">Tài khoản nhận thanh toán</div><div class="panel-sub">Khách được xem thông tin này trong mục Thanh toán.</div></div></div><form id="bankSettingsForm" class="settings-form"><div class="field"><label>Ngân hàng</label><input name="bank_name" required value="${esc(c.bank_name)}" placeholder="Ví dụ: Vietcombank"></div><div class="field"><label>Chủ tài khoản</label><input name="account_name" required value="${esc(c.account_name)}"></div><div class="field"><label>Số tài khoản</label><input name="account_number" required value="${esc(c.account_number)}"></div><div class="field"><label>Nội dung chuyển khoản gợi ý</label><input name="transfer_note" value="${esc(c.transfer_note)}" placeholder="Thanh toan ADS"></div><button class="btn btn-primary" type="submit">Lưu thông tin ngân hàng</button></form><hr><div class="panel-title">Ảnh mã QR chuyển khoản</div><p class="panel-sub">Chọn ảnh PNG/JPG/WebP, tối đa 300KB sau tối ưu; file lưu riêng trong Google Drive của Admin, chỉ hiển thị cho người đã đăng nhập.</p><div class="qr-upload">${c.qr_image?`<img class="qr-image" src="${esc(c.qr_image)}" alt="Mã QR hiện tại">`:'<div class="qr-missing">Chưa có ảnh QR</div>'}<input id="qrFileInput" type="file" accept="image/png,image/jpeg,image/webp"><button class="btn btn-primary" type="button" data-upload-qr>↑ Tải QR lên</button></div></div>`;}
function campaigns(){const list=state.data.campaigns.filter(x=>state.client==='all'||x.client_id===state.client);const body=list.map(x=>`<tr><td><span class="row-title">${esc(x.name)}</span><span class="row-sub">${esc(nameOf('accounts',x.account_id))}</span></td><td>${esc(nameOf('clients',x.client_id))}</td><td><span class="badge-platform"><span class="platform-dot" style="background:${platformColor(x.platform_id)}"></span>${esc(nameOf('platforms',x.platform_id))}</span></td><td class="numeric stat-strong">${money(x.daily_budget)}</td><td>${dateDisplay(x.start_date)} ${x.end_date?'— '+dateDisplay(x.end_date):'→'}</td><td>${pill(({ACTIVE:'Đang chạy',PAUSED:'Tạm dừng',DRAFT:'Dự thảo',ENDED:'Đã kết thúc'})[x.status]||x.status,x.status==='ACTIVE'?'green':x.status==='PAUSED'?'orange':'gray')}</td>${actions('campaigns',x)}</tr>`).join('');return `<div class="note-block"><strong>Ngân sách kế hoạch:</strong> Mỗi chiến dịch có ngân sách/ngày và ngày bắt đầu/kết thúc. Ngân sách tuần được tính theo số ngày nằm trong kỳ; chi phí thực tế được ghi riêng ở mục Chi phí.</div><div class="panel table-panel"><div class="panel-header"><div><div class="panel-title">Danh sách chiến dịch</div><div class="panel-sub">${list.length} chiến dịch đang được quản lý</div></div></div>${table(['Tên chiến dịch','Khách hàng','Nền tảng',{text:'Ngân sách/ngày',right:true},'Thời gian','Trạng thái','Thao tác'],body)}</div>`;}
function clients(){const list=state.data.clients;const body=list.map(x=>`<tr><td><div class="row-with-avatar">${avatar(x.name)}<span><span class="row-title">${esc(x.name)}</span><span class="row-sub">${esc(x.note||'Không có ghi chú')}</span></span></div></td><td>${esc(x.contact||'—')}</td><td>${esc(x.phone||'—')}</td><td class="numeric">${money(x.opening_balance)}</td><td>${state.data.campaigns.filter(y=>y.client_id===x.id).length}</td><td>${C.isYes(x.active)?pill('Hoạt động','green'):pill('Tạm ẩn','gray')}</td>${actions('clients',x)}</tr>`).join('');return `<div class="panel table-panel"><div class="panel-header"><div><div class="panel-title">Khách hàng & đối tác</div><div class="panel-sub">Độc lập ngân sách và số dư đối soát cho từng khách hàng</div></div></div>${table(['Khách hàng','Người liên hệ','Số điện thoại',{text:'Số dư ban đầu',right:true},'Số chiến dịch','Trạng thái','Thao tác'],body)}</div>`;}
function accounts(){const list=state.data.accounts.filter(x=>state.client==='all'||x.client_id===state.client);const owner={OWN:'Via / tài khoản của tôi',CLIENT:'Tài khoản của khách',OTHER:'Bên thứ ba'};const body=list.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${esc(nameOf('clients',x.client_id))}</td><td><span class="badge-platform"><span class="platform-dot" style="background:${platformColor(x.platform_id)}"></span>${esc(nameOf('platforms',x.platform_id))}</span></td><td>${esc(owner[x.owner]||x.owner)}</td><td>${C.isYes(x.active)?pill('Hoạt động','green'):pill('Tạm ẩn','gray')}</td>${actions('accounts',x)}</tr>`).join('');return `<div class="panel table-panel"><div class="panel-header"><div><div class="panel-title">Tài khoản chạy quảng cáo</div><div class="panel-sub">Theo dõi ai sở hữu via/tài khoản trên từng nền tảng</div></div></div>${table(['Tên tài khoản','Khách hàng','Nền tảng','Quyền sở hữu','Trạng thái','Thao tác'],body)}</div>`;}
function platforms(){const list=state.data.platforms;const body=list.map(x=>`<tr><td><span class="badge-platform"><span class="platform-dot" style="background:${platformColor(x.id)}"></span><strong>${esc(x.name)}</strong></span></td><td>${state.data.accounts.filter(y=>y.platform_id===x.id).length}</td><td>${state.data.campaigns.filter(y=>y.platform_id===x.id).length}</td><td>${C.isYes(x.active)?pill('Đang dùng','green'):pill('Tạm ẩn','gray')}</td>${actions('platforms',x)}</tr>`).join('');return `<div class="panel table-panel"><div class="panel-header"><div><div class="panel-title">Nền tảng đang quản lý</div><div class="panel-sub">Thêm mới Google Search, Zalo, Shopee Ads… theo nhu cầu</div></div></div>${table(['Tên nền tảng','Số tài khoản','Số chiến dịch','Trạng thái','Thao tác'],body)}</div>`;}
function settlements(){const list=rows();if(!list.length)return `<div class="panel"><div class="empty">Thêm khách hàng để bắt đầu đối soát.</div></div>`;
 let h=`<div class="print-only"><h2>BIÊN BẢN ĐỐI SOÁT QUẢNG CÁO</h2><p>Kỳ ${dateDisplay(state.week)} — ${dateDisplay(C.addDays(state.week,6))}</p></div>`;
 for(const row of list){const cp=state.data.campaigns.filter(x=>x.client_id===row.clientId);const spend=weeklyExpenses().filter(x=>cp.some(c=>c.id===x.campaign_id));const pays=weeklyPayments().filter(x=>x.client_id===row.clientId);
 const byCampaign=cp.map(x=>({...x,actual:spend.filter(z=>z.campaign_id===x.id).reduce((s,z)=>s+C.num(z.amount),0),plan:C.planned(x,state.week)})).filter(x=>x.plan||x.actual);
 const closeButton=!canEdit('closings')?'':row.status==='CONFIRMED'?`<button class="btn btn-small btn-soft" data-close="${esc(row.clientId)}" data-status="OPEN">↶ Mở kỳ</button>`:`<button class="btn btn-small btn-primary" data-close="${esc(row.clientId)}" data-status="CONFIRMED">✓ Xác nhận chốt</button>`;
 h+=`<div class="panel settle-card"><div class="settle-head"><div><h3>${esc(row.client.name)}</h3><p>Kỳ: ${dateDisplay(state.week)} — ${dateDisplay(C.addDays(state.week,6))} &nbsp; • &nbsp; ${row.status==='CONFIRMED'?'Đã khóa số liệu':'Chưa xác nhận'}</p></div>${row.status==='CONFIRMED'?pill('Đã chốt','green'):pill('Cần đối soát','orange')}</div>
 <div class="settle-grid"><div class="settle-cell"><span>Ngân sách dự kiến</span><strong>${money(row.planned)}</strong></div><div class="settle-cell"><span>Chi phí thực tế</span><strong>${money(row.spent)}</strong></div><div class="settle-cell"><span>Khách đã thanh toán (ròng)</span><strong>${money(row.paid)}</strong></div><div class="settle-cell"><span>Số dư đầu kỳ</span><strong>${money(row.opening)}</strong></div><div class="settle-cell"><span>Chênh lệch ngân sách</span><strong class="${row.planned-row.spent>=0?'text-green':'text-red'}">${money(row.planned-row.spent)}</strong></div><div class="settle-cell"><span>Số dư cuối kỳ</span><strong class="${row.ending>=0?'text-green':'text-red'}">${money(row.ending)}</strong></div></div>
 <div class="settle-detail"><div class="split-columns"><div><div class="settle-detail-title">Chi tiết theo chiến dịch</div><table class="data-compact"><tr><th>Chiến dịch</th><th>Thực tế</th></tr>${byCampaign.map(c=>`<tr><td>${esc(c.name)} <span class="row-sub">Dự kiến: ${money(c.plan)}</span></td><td>${money(c.actual)}</td></tr>`).join('')||'<tr><td colspan="2">Không có chiến dịch</td></tr>'}</table></div><div><div class="settle-detail-title">Lịch sử thanh toán của kỳ</div><table class="data-compact"><tr><th>Ngày / Loại</th><th>Số tiền</th></tr>${pays.map(p=>`<tr><td>${dateDisplay(p.date)} • ${esc(payLabel(p))}</td><td class="${p.type==='REFUND'?'text-red':'text-green'}">${p.type==='REFUND'?'-':'+'}${money(p.amount)}</td></tr>`).join('')||'<tr><td colspan="2">Chưa ghi nhận thanh toán</td></tr>'}</table></div></div></div>
 <div class="settle-footer"><div><small>${row.ending>=0?'Số tiền dư được chuyển sang kỳ tiếp theo':'Số tiền khách cần thanh toán bổ sung'}</small><div class="balance ${row.ending>=0?'text-green':'text-red'}">${money(Math.abs(row.ending))}</div></div><div class="section-actions">${closeButton}</div></div></div>`;
 }return h+'<div class="note-block"><strong>Lưu ý:</strong> Chỉ giao dịch Admin đã xác nhận nhận tiền mới cộng vào số dư. Thanh toán được gán theo kỳ đối soát, không nhất thiết theo ngày nhận tiền. Chốt kỳ sẽ khóa thay đổi chi phí và thanh toán thuộc kỳ đó; chỉ ADMIN được mở lại kỳ.</div>';
}
function opts(entity,filter=()=>true){return state.data[entity].filter(filter).map(x=>({value:x.id,label:x.name}));}
const schema = {
 users:[['email','Email Google của khách','email',true],['name','Tên hiển thị','text',true],['role','Vai trò','select',true,[['CLIENT','Khách hàng (chỉ xem dữ liệu của mình)'],['ADMIN','Quản trị hệ thống'],['EDITOR','Nhân viên nhập chi phí'],['VIEWER','Chỉ xem toàn hệ thống']]],['client_id','Gắn với khách hàng','entity',false,'clients'],['active','Trạng thái','select',true,[['TRUE','Hoạt động'],['FALSE','Tạm khóa']]]],
 clients:[['name','Tên khách hàng','text',true],['contact','Người liên hệ','text'],['phone','Số điện thoại','tel'],['opening_balance','Số dư ban đầu (VND)','number',true],['active','Trạng thái','select',true,[['TRUE','Hoạt động'],['FALSE','Tạm ẩn']]],['note','Ghi chú','textarea']],
 platforms:[['name','Tên nền tảng','text',true],['active','Trạng thái','select',true,[['TRUE','Hoạt động'],['FALSE','Tạm ẩn']]]],
 accounts:[['name','Tên tài khoản / Via','text',true],['client_id','Khách hàng','entity',true,'clients'],['platform_id','Nền tảng','entity',true,'platforms'],['owner','Tài khoản thuộc về','select',true,[['OWN','Tôi / đơn vị chạy ads'],['CLIENT','Khách hàng'],['OTHER','Bên thứ ba']]],['active','Trạng thái','select',true,[['TRUE','Hoạt động'],['FALSE','Tạm ẩn']]]],
 campaigns:[['name','Tên chiến dịch','text',true],['client_id','Khách hàng','entity',true,'clients'],['platform_id','Nền tảng','entity',true,'platforms'],['account_id','Tài khoản quảng cáo','account',true],['daily_budget','Ngân sách mỗi ngày (VND)','number',true],['start_date','Ngày bắt đầu','date',true],['end_date','Ngày kết thúc (để trống nếu chưa có)','date'],['status','Trạng thái','select',true,[['ACTIVE','Đang chạy'],['PAUSED','Tạm dừng'],['ENDED','Đã kết thúc'],['DRAFT','Dự thảo']]]],
 expenses:[['campaign_id','Chiến dịch','campaign',true],['date','Ngày phát sinh','date',true],['amount','Chi phí thực tế (VND)','number',true],['note','Ghi chú / biên lai','textarea']],
 payments:[['client_id','Khách hàng','entity',true,'clients'],['week_start','Gán vào tuần đối soát (chọn ngày bất kỳ trong tuần)','date',true],['date','Ngày thực nhận / hoàn tiền','date',true],['type','Loại giao dịch','select',true,[['RECEIVE','Nhận tiền'],['REFUND','Hoàn tiền']]],['amount','Số tiền (VND)','number',true],['method','Phương thức','select',true,[['BANK','Chuyển khoản'],['CASH','Tiền mặt'],['OTHER','Khác']]],['reference','Mã giao dịch','text'],['note','Ghi chú','textarea']]
};
function fieldHTML(f,record){const [key,label,type,required,options]=f;const value=record[key] ?? ({opening_balance:'0',daily_budget:'100000',active:'TRUE',owner:'OWN',status:'ACTIVE',role:'CLIENT',type:'RECEIVE',method:'BANK',date:nowISO(),week_start:state.week,start_date:state.week}[key]||'');const req=required?'required':'';let html='';
 if(type==='textarea')html=`<textarea id="f_${key}" name="${key}" ${req}>${esc(value)}</textarea>`;
 else if(type==='select'||type==='entity'||type==='campaign'||type==='account'){let list=type==='select'?options.map(([value,label])=>({value,label})):type==='entity'?opts(options):type==='campaign'?opts('campaigns',x=>state.client==='all'||x.client_id===state.client):opts('accounts');html=`<select name="${key}" id="f_${key}" ${req}><option value="">— Chọn —</option>${list.map(x=>`<option value="${esc(x.value)}" ${String(x.value)===String(value)?'selected':''}>${esc(x.label)}</option>`).join('')}</select>`;}
 else html=`<input id="f_${key}" name="${key}" type="${type}" ${req} ${type==='number'?(key==='opening_balance'?'step="1"':'min="0" step="1"'):''} value="${esc(value)}" />`;
 return `<div class="field ${type==='textarea'?'full':''}"><label for="f_${key}">${esc(label)} ${required?'<span class="required">*</span>':''}</label>${html}</div>`;
}
let modalState=null;
function openModal(entity,record={}){
 if(!schema[entity])return; if(!canEdit(entity)){toast('Bạn không có quyền chỉnh sửa mục này','error');return;}
 modalState={entity,old:record};$('modalTitle').textContent=(record.id?'Chỉnh sửa ':'Thêm ')+({clients:'khách hàng',platforms:'nền tảng',accounts:'tài khoản',campaigns:'chiến dịch',expenses:'chi phí',payments:'thanh toán',users:'tài khoản đăng nhập'})[entity];$('modalEyebrow').textContent='THÔNG TIN '+({clients:'KHÁCH HÀNG',platforms:'NỀN TẢNG',accounts:'TÀI KHOẢN QUẢNG CÁO',campaigns:'CHIẾN DỊCH',expenses:'CHI PHÍ',payments:'THANH TOÁN',users:'ĐĂNG NHẬP'})[entity];$('modalBody').innerHTML=schema[entity].map(f=>fieldHTML(f,record)).join('');$('overlay').classList.remove('hidden');
 if(entity==='users' && record.id){$('f_email').readOnly=true;}
 if(entity==='campaigns') { const update=()=>{const el=$('f_account_id'),current=el.value||record.account_id;const client=$('f_client_id').value,platform=$('f_platform_id').value;const options=opts('accounts',x=>(!client||x.client_id===client)&&(!platform||x.platform_id===platform));el.innerHTML='<option value="">— Chọn —</option>'+options.map(x=>`<option value="${esc(x.value)}" ${current===x.value?'selected':''}>${esc(x.label)}</option>`).join('');};$('f_client_id').addEventListener('change',update);$('f_platform_id').addEventListener('change',update);update();}
}
function openPaymentRequest(){
 if(!isClient()&&!isAdmin())return;
 const clientId=isClient()?state.me.client_id:state.client;
 if(!clientId||clientId==='all'){toast('Chọn khách hàng cần xác nhận thanh toán.','error');return;}
 const r=C.calc(state.data,clientId,state.week),amount=Math.max(0,-r.ending);
 modalState={entity:'paymentRequest',old:{}};
 $('modalEyebrow').textContent='KHÁCH HÀNG XÁC NHẬN';$('modalTitle').textContent='Tôi đã chuyển khoản';
 $('modalBody').innerHTML=`<div class="field full"><div class="payment-guide">Chỉ bấm khi bạn đã chuyển khoản thực tế. Sau đó Admin sẽ kiểm tra ngân hàng và bấm <b>"Đã nhận được tiền"</b>.</div></div>${[['amount','Số tiền đã chuyển (VND)','number',String(amount||''), 'required min="1" step="1"'],['date','Ngày chuyển khoản','date',nowISO(),'required max="'+nowISO()+'"'],['week_start','Kỳ đối soát cần thanh toán','date',state.week,'required'],['reference','Mã giao dịch (nếu có)','text','',''],['note','Ghi chú','text','','']].map(([k,label,type,v,attrs])=>`<div class="field ${k==='note'?'full':''}"><label>${label}</label><input name="${k}" type="${type}" ${attrs} value="${esc(v)}"></div>`).join('')}`;
 $('saveModal').textContent='✓ Xác nhận đã thanh toán';$('overlay').classList.remove('hidden');
}
async function requestTransfer(record){
 setLoading(true);
 try{
  if(state.mode==='live'){await api('requestPayment',{record});await loadLive();}
  else {state.data.payments.unshift({...record,id:id(),type:'RECEIVE',method:'BANK',status:'PENDING',requested_by:'khach.demo@gmail.com',customer_confirmed_at:new Date().toISOString()});persistDemo();}
  toast('Đã báo chuyển khoản. Đang chờ Admin xác nhận đã nhận tiền.','success');render();
 }finally{setLoading(false);}
}
async function transitionTransfer(id,target){
 const msg=target==='CONFIRMED'?'Bạn đã kiểm tra ngân hàng và thực sự nhận đủ khoản tiền này?':'Từ chối xác nhận nhận tiền cho giao dịch này?';
 if(!confirm(msg))return;
 setLoading(true);
 try{
  if(state.mode==='live'){await api(target==='CONFIRMED'?'confirmPayment':'rejectPayment',{id});await loadLive();}
  else {const p=state.data.payments.find(x=>x.id===id);if(!p||payStatus(p)!=='PENDING')throw Error('Trạng thái giao dịch đã thay đổi');if(target==='CONFIRMED'&&state.data.closings.some(x=>x.client_id===p.client_id&&x.status==='CONFIRMED'&&x.week_start>=p.week_start))throw Error('Kỳ đối soát đã chốt, hãy mở kỳ trước');p.status=target;p.admin_confirmed_at=target==='CONFIRMED'?new Date().toISOString():'';p.confirmed_by=target==='CONFIRMED'?'demo.admin@gmail.com':'';persistDemo();}
  toast(target==='CONFIRMED'?'Đã xác nhận thực nhận — tiền được tính vào đối soát.':'Đã từ chối yêu cầu.','success');render();
 }catch(e){toast(e.message,'error')}finally{setLoading(false)}
}
async function uploadQr(){const file=$('qrFileInput')?.files?.[0];if(!file)return toast('Vui lòng chọn ảnh mã QR','error');if(!['image/png','image/jpeg','image/webp'].includes(file.type))return toast('Chỉ hỗ trợ PNG/JPG/WebP','error');if(file.size>300000)return toast('Ảnh phải dưới 300KB, vui lòng nén trước khi tải lên.','error');
 try{const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});setLoading(true);if(state.mode==='live'){const r=await api('uploadPaymentQr',{mime:file.type,base64});state.paymentConfig=r.paymentConfig;}else{state.paymentConfig.qr_image='data:'+file.type+';base64,'+base64;persistDemo();}toast('Đã cập nhật mã QR','success');render()}catch(e){toast(e.message,'error')}finally{setLoading(false)}
}
async function saveBankConfig(e){e.preventDefault();const record=Object.fromEntries(new FormData(e.target));try{setLoading(true);if(state.mode==='live'){const r=await api('savePaymentConfig',{record});state.paymentConfig=r.paymentConfig;}else{Object.assign(state.paymentConfig,record);persistDemo();}toast('Đã lưu tài khoản nhận tiền','success');render()}catch(err){toast(err.message,'error')}finally{setLoading(false)}}
function closeModal(){$('saveModal').textContent='Lưu thông tin';$('overlay').classList.add('hidden');modalState=null;$('entityForm').reset();}
async function confirmClosing(clientId,status){const row=C.calc(state.data,clientId,state.week);if(status==='CONFIRMED' && nowISO()<C.addDays(state.week,7)){toast('Chỉ được chốt kỳ từ thứ Hai tuần kế tiếp.','error');return;}if(state.mode==='live' && state.me?.role!=='ADMIN'){toast('Chỉ ADMIN được chốt hoặc mở kỳ','error');return;}if(!confirm(status==='CONFIRMED'?'Xác nhận chốt kỳ này? Các giao dịch của kỳ sẽ bị khóa.':'Mở lại kỳ này để chỉnh sửa số liệu?'))return;
 let existing=state.data.closings.find(x=>x.client_id===clientId&&x.week_start===state.week);
 const record={...existing,id:existing?.id||id(),client_id:clientId,week_start:state.week,status,planned:String(row.planned),spent:String(row.spent),paid:String(row.paid),opening:String(row.opening),ending:String(row.ending),closed_at:status==='CONFIRMED'?new Date().toISOString():''};
 try{await save('closings',record)}catch{}
}
function escapeCsv(v){const s=String(v??'');const safe=(!/^-?\d+(\.\d+)?$/.test(s) && /^[=+@\-\t\r]/.test(s))?"'"+s:s;return '"'+safe.replace(/"/g,'""')+'"';}
function exportCsv(){let title='',heads=[],data=[];
 if(state.page==='dashboard'||state.page==='settlements'){title='doi-soat';heads=['Khách hàng','Tuần bắt đầu','Tuần kết thúc','Dự kiến','Thực tế','Đã nhận ròng','Số dư đầu','Số dư cuối','Trạng thái'];data=rows().map(x=>[x.client.name,x.week,C.addDays(x.week,6),x.planned,x.spent,x.paid,x.opening,x.ending,x.status]);}
 if(state.page==='expenses'){title='chi-phi';heads=['Ngày','Khách hàng','Nền tảng','Chiến dịch','Số tiền','Ghi chú'];data=weeklyExpenses().map(x=>{const c=getBy('campaigns',x.campaign_id);return[x.date,nameOf('clients',c?.client_id),nameOf('platforms',c?.platform_id),c?.name,x.amount,x.note]})}
 if(state.page==='payments'){title='thanh-toan';heads=['Ngày','Kỳ đối soát','Khách hàng','Loại','Số tiền','Trạng thái','Mã giao dịch','Khách báo','Admin xác nhận','Ghi chú'];data=weeklyPayments().map(x=>[x.date,x.week_start,nameOf('clients',x.client_id),x.type,x.amount,payLabel(x),x.reference,x.customer_confirmed_at||'',x.admin_confirmed_at||'',x.note])}
 if(!title)return;const text='\ufeff'+[heads,...data].map(row=>row.map(escapeCsv).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`adledger-${title}-${state.week}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('Đã xuất báo cáo CSV','success');
}
async function handleSubmit(e){e.preventDefault();if(!modalState)return;const {entity,old}=modalState;const obj={...old,id:old.id||id()};const form=new FormData(e.currentTarget);for(const [key,value] of form)obj[key]=String(value).trim();if(entity==='paymentRequest'){obj.client_id=state.me?.client_id||state.client;obj.week_start=C.monday(obj.week_start);if(!Number.isSafeInteger(Number(obj.amount))||Number(obj.amount)<=0){toast('Số tiền phải là số nguyên VND lớn hơn 0','error');return;}$('saveModal').disabled=true;try{await requestTransfer(obj);closeModal()}catch(e){toast(e.message,'error')}finally{$('saveModal').disabled=false}return;}
 if(entity==='users')obj.id=obj.email;
 if(entity==='payments')obj.week_start=C.monday(obj.week_start);if(entity==='campaigns'){const acc=getBy('accounts',obj.account_id);if(!acc||acc.client_id!==obj.client_id||acc.platform_id!==obj.platform_id){toast('Tài khoản quảng cáo không khớp khách hàng và nền tảng','error');return;}if(obj.end_date&&obj.end_date<obj.start_date){toast('Ngày kết thúc phải sau ngày bắt đầu','error');return;}}
 if(entity==='expenses'){if(C.num(obj.amount)<0)return toast('Số tiền không hợp lệ','error');const cp=getBy('campaigns',obj.campaign_id);if(cp&&(obj.date<cp.start_date||(cp.end_date&&obj.date>cp.end_date)))return toast('Ngày chi phí nằm ngoài thời gian chạy của chiến dịch ('+dateDisplay(cp.start_date)+' → '+(cp.end_date?dateDisplay(cp.end_date):'nay')+').','error');}
 $('saveModal').disabled=true;try{await save(entity,obj);closeModal()}catch{}finally{$('saveModal').disabled=false}
}
async function logout(){if(state.mode==='live'){try{await api('logout')}catch{}localStorage.removeItem('adledger_session');state.token='';state.me=null;showLogin();}else{showLogin();}}
function bind(){
 $('mainNav').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b){state.page=b.dataset.page;render();}});
 $('view').addEventListener('click',async e=>{
 const nav=e.target.closest('[data-page]');if(nav){state.page=nav.dataset.page;render();return;}
 const edit=e.target.closest('[data-edit]');if(edit){openModal(edit.dataset.edit,getBy(edit.dataset.edit,edit.dataset.id));return;}
 const delBtn=e.target.closest('[data-delete]');if(delBtn){await del(delBtn.dataset.delete,getBy(delBtn.dataset.delete,delBtn.dataset.id));return;}
 const confirmPay=e.target.closest('[data-confirm-payment]');if(confirmPay){await transitionTransfer(confirmPay.dataset.confirmPayment,'CONFIRMED');return;}
 const rejectPay=e.target.closest('[data-reject-payment]');if(rejectPay){await transitionTransfer(rejectPay.dataset.rejectPayment,'REJECTED');return;}
 const uploadBtn=e.target.closest('[data-upload-qr]');if(uploadBtn){await uploadQr();return;}
 const requestBtn=e.target.closest('[data-request-payment]');if(requestBtn){openPaymentRequest();return;}
 const close=e.target.closest('[data-close]');if(close){await confirmClosing(close.dataset.close,close.dataset.status);return;}
 });
 $('headingAction').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-request-payment')){openPaymentRequest();return;}if(b.dataset.create)openModal(b.dataset.create);else if(b.dataset.action==='export')exportCsv();else if(b.dataset.action==='print')window.print();});
 $('clientFilter').addEventListener('change',e=>{state.client=e.target.value;render();});
 $('weekDate').addEventListener('change',e=>{if(e.target.value){state.week=C.monday(e.target.value);render();}});
 $('prevWeek').addEventListener('click',()=>{state.week=C.addDays(state.week,-7);render();});$('nextWeek').addEventListener('click',()=>{state.week=C.addDays(state.week,7);render();});
 $('refreshBtn').addEventListener('click',async()=>{if(state.mode==='live'){try{await loadLive();toast('Đã cập nhật dữ liệu','success');render()}catch(e){toast(e.message,'error')}}else {toast('Chế độ Demo: Dữ liệu lưu cục bộ trong trình duyệt')}});
 $('view').addEventListener('submit',e=>{if(e.target.id==='bankSettingsForm')saveBankConfig(e)});$('entityForm').addEventListener('submit',handleSubmit);$('closeModal').addEventListener('click',closeModal);$('cancelModal').addEventListener('click',closeModal);$('overlay').addEventListener('click',e=>{if(e.target===$('overlay'))closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('overlay').classList.contains('hidden'))closeModal()});
 $('demoRoleBtn').addEventListener('click',()=>{if(state.mode!=='demo')return;const customer=isClient();state.me=customer?{name:'Demo Admin',role:'ADMIN'}:{name:'Khách hàng A',role:'CLIENT',client_id:'cl1'};state.client=customer?'all':'cl1';state.page='dashboard';showApp();});$('demoLoginBtn').addEventListener('click',enterDemo);$('logoutBtn').addEventListener('click',logout);$('menuBtn').addEventListener('click',()=>$('sidebar').classList.toggle('open'));document.addEventListener('click',e=>{const t=e.target;if(t?.closest&&!t.closest('#sidebar')&&!t.closest('#menuBtn'))$('sidebar').classList.remove('open');});
}
bind();bootstrap();
})();
